{
  "summary": "The reader is an undergraduate in computer science who has taken discrete mathematics, data structures and algorithms, introductory theory of computation, and the linear algebra and calculus that accompany such a degree. They are fluent with asymptotic analysis, recurrences, binary representation and bitwise operations, modular arithmetic, matrices and rank, vector spaces over the reals, and complex numbers including roots of unity; they know the schoolbook and Karatsuba multiplication algorithms and what a Turing machine with tapes is. They have not studied abstract algebra beyond basics, the FFT's algebraic variants, number-theoretic transforms, finite fields beyond arithmetic mod 2, analytic number theory, numerical analysis of rounding error, or any bit-complexity multiplication algorithm.",
  "known": [
    {
      "name": "Asymptotic notation beyond big-O",
      "aliases": ["Omega notation", "Theta notation", "little-o", "o(...)", "Ω", "Θ", "asymptotically smaller", "worst-case running time"],
      "gloss": "Ω gives asymptotic lower bounds, Θ gives tight bounds, and o(g) means the ratio f/g tends to zero; worst-case time is the maximum running time over inputs of a given length."
    },
    {
      "name": "Limits and limit inferior",
      "aliases": ["liminf", "limsup", "limit of a ratio", "lim inf", "eventually", "for all sufficiently large n"],
      "gloss": "The limit of a sequence or ratio as n grows without bound, and its liminf, the smallest value approached by infinitely many terms."
    },
    {
      "name": "Logarithms, exponentials, floors and ceilings",
      "aliases": ["log base 2", "lg n", "log_2", "natural logarithm", "floor function", "ceiling function", "powers of two", "iterated logarithm", "log star"],
      "gloss": "The base-2 and natural logarithms and exponentials with their identities, and the floor and ceiling functions that round a real number down or up to an integer."
    },
    {
      "name": "Recurrences and geometric sums",
      "aliases": ["recurrence relation", "solving recurrences", "geometric series", "geometric sum", "unrolling a recurrence", "divide and conquer"],
      "gloss": "Bounding the cost T(k) ≤ a·T(k−1) + c by unrolling it, which for a ratio a < 1 gives a convergent geometric series dominated by its largest term."
    },
    {
      "name": "Positional number systems and carries",
      "aliases": ["binary representation", "radix representation", "base-b digits", "bit string", "most significant bit", "carry propagation", "schoolbook addition", "padding with leading zeros"],
      "gloss": "Writing a nonnegative integer as a string of digits in a fixed base (such as 2) with the most significant digit first, and adding digit strings by propagating carries."
    },
    {
      "name": "Schoolbook and Karatsuba multiplication",
      "aliases": ["grade-school multiplication", "long multiplication", "Karatsuba", "divide-and-conquer multiplication", "Toom-Cook", "quadratic multiplication"],
      "gloss": "Long multiplication costs O(n²) bit operations for n-bit integers, and Karatsuba's divide-and-conquer trick with three half-size products lowers this to O(n^{log₂3})."
    },
    {
      "name": "Bitwise operations and XOR",
      "aliases": ["exclusive or", "XOR", "bitwise exclusive or", "addition modulo 2", "bit flip", "parity", "bit shift", "bit mask"],
      "gloss": "Operations that act on each bit independently, in particular XOR, which is addition of bits modulo 2 and is its own inverse."
    },
    {
      "name": "Modular arithmetic",
      "aliases": ["integers modulo q", "Z/qZ", "congruence", "residues", "units modulo q", "invertible residues", "arithmetic mod q", "Chinese remainder theorem for integers"],
      "gloss": "Arithmetic on remainders modulo q, where addition and multiplication are done and then reduced, and a residue is invertible exactly when it is coprime to q."
    },
    {
      "name": "Primes, coprimality and the extended Euclidean algorithm",
      "aliases": ["prime numbers", "relatively prime", "pairwise coprime", "gcd", "greatest common divisor", "Euclid's algorithm", "Bezout identity", "modular inverse", "odd primes", "primality testing by trial division"],
      "gloss": "Prime numbers and pairwise coprime integers, and the extended Euclidean algorithm, which computes gcd(a,b) and integers x,y with ax + by = gcd(a,b), hence modular inverses."
    },
    {
      "name": "Roots of unity",
      "aliases": ["primitive root of unity", "nth roots of unity", "e^{2πi/n}", "unit complex numbers", "complex exponential", "Euler's formula", "twiddle factor", "N-th root of unity"],
      "gloss": "The complex solutions of z^n = 1, namely e^{2πik/n}, whose powers cycle with period n and sum to zero over a full period."
    },
    {
      "name": "Matrices and linear maps",
      "aliases": ["matrix multiplication", "matrix inverse", "invertible matrix", "linear operator", "linear transformation", "identity matrix", "diagonal matrix", "unitary or involution matrix", "matrix-vector product", "linear combination"],
      "gloss": "A linear map is represented by a matrix acting on vectors; matrices multiply by composing maps, and a square matrix is invertible exactly when its inverse map exists."
    },
    {
      "name": "Vector spaces, subspaces, dimension and rank",
      "aliases": ["subspace", "span", "basis", "linear independence", "dimension", "rank of a matrix", "rank-nullity", "kernel", "image", "column space", "direct sum", "quotient space"],
      "gloss": "A vector space has a dimension equal to the size of any basis, a subspace is a subset closed under linear combinations, and the rank of a matrix is the dimension of its image."
    },
    {
      "name": "Inner products, bilinear forms and orthogonal complements",
      "aliases": ["bilinear form", "dot product", "orthogonality", "orthogonal complement", "orthogonal subspace", "nondegenerate pairing", "inner product space", "pairing"],
      "gloss": "A bilinear form is a map on pairs of vectors linear in each argument (the dot product being the basic example), and the orthogonal complement of a subspace is the set of vectors orthogonal to all of it, with dimension complementary to the subspace's."
    },
    {
      "name": "Gaussian elimination and triangular matrices",
      "aliases": ["row reduction", "LU decomposition", "lower triangular matrix", "upper triangular matrix", "elementary row operations", "back substitution", "unit triangular matrix", "row echelon form"],
      "gloss": "Row operations reduce a matrix to triangular or echelon form, and triangular matrices have their nonzero entries on one side of the diagonal and are invertible when the diagonal is nonzero."
    },
    {
      "name": "Permutations, bijections and permutation matrices",
      "aliases": ["permutation", "bijection", "one-to-one correspondence", "inverse permutation", "partial permutation", "reordering of an array", "sorting network", "transposition of indices", "permutation matrix"],
      "gloss": "A permutation is a bijection of a finite index set onto itself, acting on an array by reordering its entries, and corresponds to a 0/1 matrix with a single one in each row and column."
    },
    {
      "name": "Arithmetic modulo 2 and linear algebra over F_2",
      "aliases": ["F_2", "GF(2)", "binary field", "field with two elements", "matrices over F_2", "GL(m, F_2)", "mod 2 arithmetic", "boolean linear algebra"],
      "gloss": "The field of two elements 0 and 1 with addition equal to XOR and multiplication equal to AND, over which vector spaces, matrices and invertibility behave as over any field."
    },
    {
      "name": "Finite sets, subsets and counting",
      "aliases": ["Cartesian product", "subset intersection", "set cardinality", "binomial coefficient", "inclusion-exclusion", "product of index sets", "power set", "three-element subsets", "pigeonhole"],
      "gloss": "Basic combinatorics of finite sets: the Cartesian product of index sets, cardinalities of intersections of subsets, and counting subsets of a given size by binomial coefficients."
    },
    {
      "name": "Circuits and directed acyclic graphs",
      "aliases": ["arithmetic circuit", "linear circuit", "wires and gates", "directed graph", "DAG", "network of gates", "fan-in", "source and sink nodes", "layered network"],
      "gloss": "A computation drawn as a directed acyclic graph whose nodes are gates applying simple operations to the values on incoming wires, with sources as inputs and sinks as outputs."
    },
    {
      "name": "Vector norms and the triangle inequality",
      "aliases": ["sup norm", "maximum norm", "infinity norm", "‖·‖_∞", "modulus bound", "triangle inequality", "operator norm", "error bound", "disk bound"],
      "gloss": "A norm assigns each vector a size (the sup norm is the largest absolute entry), satisfies ‖u+v‖ ≤ ‖u‖+‖v‖, and lets one bound how much a linear map can enlarge errors."
    },
    {
      "name": "Fixed-point numbers, dyadic rationals and rounding",
      "aliases": ["fixed point arithmetic", "dyadic rational", "binary fraction", "rounding to nearest integer", "truncation", "round-off error", "precision in bits", "numbers with p fractional bits", "grid of spacing 2^{-p}"],
      "gloss": "Numbers stored as integer multiples of 2^{−p} (a binary fraction with p fractional bits), where operations are rounded or truncated back to this grid at a cost of at most half a grid step or one step of error."
    },
    {
      "name": "Row-major order and matrix transposition",
      "aliases": ["row-major layout", "array layout", "transposing a matrix", "matrix transpose", "k×k binary matrix", "lexicographic address", "two-dimensional array as a list"],
      "gloss": "A two-dimensional array is stored as a single sequence row by row, and transposition swaps its row and column indices, which on a sequential store means a nontrivial rearrangement of the data."
    },
    {
      "name": "Subroutines and reductions between problems",
      "aliases": ["black-box subroutine", "reduction", "calling a subroutine", "oracle call", "problem reduction", "conditional lower bound", "composition of algorithms", "uniform algorithm"],
      "gloss": "An algorithm may call another algorithm as a black box and pay its cost per call; a reduction from problem A to B bounds A's complexity by B's plus the conversion cost."
    },
    {
      "name": "Convolution of sequences",
      "aliases": ["linear convolution", "polynomial multiplication as convolution", "product of coefficient sequences", "discrete convolution", "convolution theorem"],
      "gloss": "The convolution of two sequences has entry j equal to the sum of u_k v_{j−k}, which is exactly the coefficient list of the product of the polynomials with those coefficients."
    }
  ]
}
EOF
